**Complete Example:**
```java
import org.openqa.selenium.Alert;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;

public class AlertHandling {
    public void handleAlert(WebDriver driver) {
        // Click button that triggers alert
        driver.findElement(By.id("alertButton")).click();

        // Wait for alert to appear
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        Alert alert = wait.until(ExpectedConditions.alertIsPresent());

        // Get alert text
        String alertText = alert.getText();
        System.out.println("Alert message: " + alertText);

        // Accept alert
        alert.accept();
    }

    public void handlePrompt(WebDriver driver) {
        driver.findElement(By.id("promptButton")).click();

        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        Alert prompt = wait.until(ExpectedConditions.alertIsPresent());

        // Get prompt message
        System.out.println("Prompt: " + prompt.getText());

        // Enter text
        prompt.sendKeys("John Doe");

        // Click OK
        prompt.accept();
    }

    public void handleConfirmation(WebDriver driver, boolean accept) {
        driver.findElement(By.id("confirmButton")).click();

        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        Alert confirm = wait.until(ExpectedConditions.alertIsPresent());

        if (accept) {
            confirm.accept();  // Click OK
        } else {
            confirm.dismiss(); // Click Cancel
        }
    }
}
```

**Best Practices:**
- Always use explicit wait for alerts
- Get alert text before accepting/dismissing
- Handle in try-catch for robustness
- Verify alert text matches expectations

