public class DropdownVerification {
    public void verifyDropdown(WebDriver driver) {
        Select countryDropdown = new Select(driver.findElement(By.id("country")));

        // Get all options
        List<WebElement> allOptions = countryDropdown.getOptions();
        System.out.println("Total countries: " + allOptions.size());

        // Verify dropdown has expected options
        Assert.assertTrue(allOptions.size() > 0, "Dropdown is empty");

        // Select an option
        countryDropdown.selectByVisibleText("India");

        // Verify selection
        WebElement selected = countryDropdown.getFirstSelectedOption();
        String selectedText = selected.getText();
        String selectedValue = selected.getAttribute("value");

        Assert.assertEquals(selectedText, "India", "Wrong option selected");
        Assert.assertEquals(selectedValue, "in", "Wrong value selected");

        // Verify it's not multi-select
        Assert.assertFalse(countryDropdown.isMultiple(), "Should be single-select");

        System.out.println("✓ Dropdown verification passed");
    }

    public void printAllOptions(WebDriver driver) {
        Select dropdown = new Select(driver.findElement(By.id("dropdown")));
        List<WebElement> options = dropdown.getOptions();

        System.out.println("\n=== Dropdown Options ===");
        for (int i = 0; i < options.size(); i++) {
            WebElement option = options.get(i);
            System.out.println(i + ". " + option.getText() + 
                             " [value=" + option.getAttribute("value") + "]");
        }
    }

    public boolean verifyOptionExists(WebDriver driver, String optionText) {
        Select dropdown = new Select(driver.findElement(By.id("dropdown")));
        List<WebElement> options = dropdown.getOptions();

        for (WebElement option : options) {
            if (option.getText().equals(optionText)) {
                return true;
            }
        }
        return false;
    }
}
```

