**Complete Example: Complex Form Handling**

```java
import org.openqa.selenium.*;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;
import java.util.Set;

public class ComplexFormHandling {
    private WebDriver driver;
    private WebDriverWait wait;

    public ComplexFormHandling() {
        driver = new ChromeDriver();
        driver.manage().window().maximize();
        wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    public void handleComplexForm() {
        try {
            // Navigate to page
            driver.get("https://example.com/complex-form");

            // 1. Fill form in main page
            fillMainForm();

            // 2. Handle dropdown
            handleDropdownSelection();

            // 3. Handle frame with additional fields
            handleFrameForm();

            // 4. Submit and handle alert
            submitFormWithAlert();

            // 5. Handle new window with confirmation
            handleConfirmationWindow();

            System.out.println("✓ Form submitted successfully");

        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            takeScreenshot("error");
        } finally {
            driver.quit();
        }
    }

    private void fillMainForm() {
        System.out.println("Filling main form...");

        // Wait for form to be visible
        WebElement nameField = wait.until(
            ExpectedConditions.visibilityOfElementLocated(By.id("name"))
        );

        nameField.clear();
        nameField.sendKeys("John Doe");

        WebElement emailField = driver.findElement(By.id("email"));
        emailField.clear();
        emailField.sendKeys("john@example.com");
    }

    private void handleDropdownSelection() {
        System.out.println("Handling dropdown...");

        try {
            // Wait for dropdown to be clickable
            WebElement dropdownElement = wait.until(
                ExpectedConditions.elementToBeClickable(By.id("country"))
            );

            Select countryDropdown = new Select(dropdownElement);

            // Verify dropdown is loaded with options
            if (countryDropdown.getOptions().size() == 0) {
                throw new RuntimeException("Dropdown is empty");
            }

            // Select country
            countryDropdown.selectByVisibleText("United States");

            // Verify selection
            String selected = countryDropdown.getFirstSelectedOption().getText();
            if (!selected.equals("United States")) {
                throw new RuntimeException("Country selection failed");
            }

            System.out.println("✓ Country selected: " + selected);

        } catch (Exception e) {
            System.err.println("Dropdown error: " + e.getMessage());
            throw e;
        }
    }

    private void handleFrameForm() {
        System.out.println("Handling frame form...");

        try {
            // Wait for frame to be available
            wait.until(ExpectedConditions.frameToBeAvailableAndSwitchToIt(
                By.id("detailsFrame")
            ));

            // Now in frame context
            WebElement addressField = wait.until(
                ExpectedConditions.visibilityOfElementLocated(By.id("address"))
            );
            addressField.sendKeys("123 Main Street");

            WebElement cityField = driver.findElement(By.id("city"));
            cityField.sendKeys("New York");

            // Select state from dropdown in frame
            Select stateDropdown = new Select(driver.findElement(By.id("state")));
            stateDropdown.selectByValue("NY");

            System.out.println("✓ Frame form filled");

        } catch (Exception e) {
            System.err.println("Frame handling error: " + e.getMessage());
            throw e;
        } finally {
            // Always switch back to main content
            driver.switchTo().defaultContent();
        }
    }

    private void submitFormWithAlert() {
        System.out.println("Submitting form...");

        try {
            // Click submit button
            WebElement submitButton = driver.findElement(By.id("submitBtn"));
            submitButton.click();

            // Wait for and handle confirmation alert
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());

            String alertText = alert.getText();
            System.out.println("Alert message: " + alertText);

            // Verify alert message
            if (!alertText.contains("Are you sure")) {
                throw new RuntimeException("Unexpected alert: " + alertText);
            }

            // Accept alert
            alert.accept();
            System.out.println("✓ Alert accepted");

        } catch (TimeoutException e) {
            System.err.println("Alert did not appear");
            throw e;
        }
    }

    private void handleConfirmationWindow() {
        System.out.println("Handling confirmation window...");

        try {
            // Store main window handle
            String mainWindow = driver.getWindowHandle();

            // Wait for new window to open
            wait.until(ExpectedConditions.numberOfWindowsToBe(2));

            // Get all window handles
            Set<String> allWindows = driver.getWindowHandles();

            // Switch to new window
            for (String window : allWindows) {
                if (!window.equals(mainWindow)) {
                    driver.switchTo().window(window);
                    break;
                }
            }

            // Verify confirmation message in new window
            WebElement confirmMessage = wait.until(
                ExpectedConditions.visibilityOfElementLocated(
                    By.className("success-message")
                )
            );

            String message = confirmMessage.getText();
            System.out.println("Confirmation: " + message);

            if (!message.contains("Success")) {
                throw new RuntimeException("Form submission failed");
            }

            // Close confirmation window
            driver.close();

            // Switch back to main window
            driver.switchTo().window(mainWindow);
            System.out.println("✓ Confirmation verified");

        } catch (Exception e) {
            System.err.println("Window handling error: " + e.getMessage());
            throw e;
        }
    }

