```java
import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;
import java.util.*;

public class ElementUtils {
    private WebDriver driver;
    private WebDriverWait wait;

    public ElementUtils(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
    }

    // ============ DROPDOWN UTILITIES ============

    public void selectDropdownByText(By locator, String text) {
        try {
            WebElement element = wait.until(
                ExpectedConditions.elementToBeClickable(locator)
            );
            Select select = new Select(element);
            select.selectByVisibleText(text);
            System.out.println("Selected: " + text);
        } catch (Exception e) {
            throw new RuntimeException("Failed to select dropdown: " + e.getMessage());
        }
    }

    public void selectDropdownByValue(By locator, String value) {
        try {
            Select select = new Select(wait.until(
                ExpectedConditions.presenceOfElementLocated(locator)
            ));
            select.selectByValue(value);
        } catch (Exception e) {
            throw new RuntimeException("Failed to select by value: " + e.getMessage());
        }
    }

    public String getSelectedDropdownText(By locator) {
        try {
            Select select = new Select(driver.findElement(locator));
            return select.getFirstSelectedOption().getText();
        } catch (Exception e) {
            throw new RuntimeException("Failed to get selection: " + e.getMessage());
        }
    }

    public List<String> getAllDropdownOptions(By locator) {
        List<String> optionTexts = new ArrayList<>();
        try {
            Select select = new Select(driver.findElement(locator));
            for (WebElement option : select.getOptions()) {
                optionTexts.add(option.getText());
            }
        } catch (Exception e) {
            throw new RuntimeException("Failed to get options: " + e.getMessage());
        }
        return optionTexts;
    }

    public boolean isDropdownMultiSelect(By locator) {
        try {
            Select select = new Select(driver.findElement(locator));
            return select.isMultiple();
        } catch (Exception e) {
            return false;
        }
    }

    // ============ ALERT UTILITIES ============

    public void acceptAlert() {
        try {
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());
            String alertText = alert.getText();
            alert.accept();
            System.out.println("Alert accepted: " + alertText);
        } catch (TimeoutException e) {
            System.out.println("No alert present");
        }
    }

    public void dismissAlert() {
        try {
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());
            alert.dismiss();
            System.out.println("Alert dismissed");
        } catch (TimeoutException e) {
            System.out.println("No alert present");
        }
    }

    public String getAlertText() {
        try {
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());
            return alert.getText();
        } catch (TimeoutException e) {
            return null;
        }
    }

    public void handlePromptAlert(String inputText, boolean accept) {
        try {
            Alert alert = wait.until(ExpectedConditions.alertIsPresent());
            System.out.println("Prompt: " + alert.getText());

            if (inputText != null && !inputText.isEmpty()) {
                alert.sendKeys(inputText);
            }

            if (accept) {
                alert.accept();
            } else {
                alert.dismiss();
            }
        } catch (Exception e) {
            throw new RuntimeException("Failed to handle prompt: " + e.getMessage());
        }
    }

    public boolean isAlertPresent() {
        try {
            driver.switchTo().alert();
            return true;
        } catch (NoAlertPresentException e) {
            return false;
        }
    }

    // ============ FRAME UTILITIES ============

    public void switchToFrame(String frameNameOrId) {
        try {
            wait.until(ExpectedConditions.frameToBeAvailableAndSwitchToIt(frameNameOrId));
            System.out.println("Switched to frame: " + frameNameOrId);
        } catch (Exception e) {
            throw new RuntimeException("Failed to switch to frame: " + e.getMessage());
        }
    }

    public void switchToFrameByIndex(int index) {
        try {
            wait.until(ExpectedConditions.frameToBeAvailableAndSwitchToIt(index));
            System.out.println("Switched to frame index: " + index);
        } catch (Exception e) {
            throw new RuntimeException("Failed to switch to frame: " + e.getMessage());
        }
    }

    public void switchToFrameByElement(By locator) {
        try {
            WebElement frameElement = wait.until(
                ExpectedConditions.presenceOfElementLocated(locator)
            );
            driver.switchTo().frame(frameElement);
            System.out.println("Switched to frame by element");
        } catch (Exception e) {
            throw new RuntimeException("Failed to switch to frame: " + e.getMessage());
        }
    }

    public void switchToDefaultContent() {
        driver.switchTo().defaultContent();
        System.out.println("Switched to default content");
    }

    public void switchToParentFrame() {
        driver.switchTo().parentFrame();
        System.out.println("Switched to parent frame");
    }

    public int countFrames() {
        return driver.findElements(By.tagName("iframe")).size();
    }

    // ============ WINDOW UTILITIES ============

    public String getCurrentWindowHandle() {
        return driver.getWindowHandle();
    }

    public void switchToNewWindow() {
        String mainWindow = driver.getWindowHandle();
        Set<String> allWindows = driver.getWindowHandles();

        for (String window : allWindows) {
            if (!window.equals(mainWindow)) {
                driver.switchTo().window(window);
                System.out.println("Switched to new window: " + driver.getTitle());
                return;
            }
        }
        throw new RuntimeException("No new window found");
    }

    public void switchToWindowByTitle(String title) {
        Set<String> allWindows = driver.getWindowHandles();

        for (String window : allWindows) {
            driver.switchTo().window(window);
            if (driver.getTitle().equals(title)) {
                System.out.println("Switched to window: " + title);
                return;
            }
        }
        throw new RuntimeException("Window not found: " + title);
    }

    public void switchToWindowByURL(String partialURL) {
        Set<String> allWindows = driver.getWindowHandles();

        for (String window : allWindows) {
            driver.switchTo().window(window);
            if (driver.getCurrentUrl().contains(partialURL)) {
                System.out.println("Switched to URL: " + partialURL);
                return;
            }
        }
        throw new RuntimeException("Window with URL not found: " + partialURL);
    }

    public void closeCurrentWindow(String mainWindowHandle) {
        driver.close();
        driver.switchTo().window(mainWindowHandle);
        System.out.println("Closed current window and switched back");
    }

    public void closeAllWindowsExceptMain(String mainWindowHandle) {
        Set<String> allWindows = driver.getWindowHandles();
        for (String window : allWindows) {
            if (!window.equals(mainWindowHandle)) {
                driver.switchTo().window(window);
                driver.close();
            }
        }
        driver.switchTo().window(mainWindowHandle);
        System.out.println("Closed all windows except main");
    }

    public int getWindowCount() {
        return driver.getWindowHandles().size();
    }
}
